OUT=Path(__file__).resolve().parents[1]
def read(p):return json.loads(p.read_text())

def table(rows):
    body=''.join('<tr>'+''.join(f'<td>{html.escape(str(v))}</td>' for v in row)+'</tr>' for row in rows)
    return '<table><thead><tr><th>Method</th><th>Within 1%</th><th>Within 3%</th><th>Available</th><th>Median / p90 error</th></tr></thead><tbody>'+body+'</tbody></table>'

def metrics_row(name,r):
    return [name,f"{r['correct_by_tolerance_pct_width']['1']}/{r['visible_references']}",f"{r['correct_by_tolerance_pct_width']['3']}/{r['visible_references']}",f"{r['available_visible']}/{r['visible_references']}",f"{r['median_error_pct']:.2f}% / {r['p90_error_pct']:.2f}%"]

def main():
    results=read(OUT/'reserved_evaluation/results.json');backup=read(OUT/'backup_evaluation/results.json');baseline=results['baseline']['all'];first=results['candidates']['offline']['end_to_end']['all'];second=backup['candidates']['round2']['end_to_end']['all'];box=backup['candidates']['same_pipeline_box_bottom']['end_to_end']['all'];diag=read(OUT/'round2/previous_test_diagnostic.json');runtime=read(OUT/'diagnostics/runtime.json');selection=read(OUT/'round2/frozen_selection.json');training=read(OUT/'runs/v5_attention_s17/settings.json')
    first_table=table([metrics_row('Previous pipeline',baseline),metrics_row('First frozen offline pipeline',first)]);final_table=table([metrics_row('Same pipeline, box bottoms',box),metrics_row('Same pipeline, learned support',second)]);cont=diag['continuity'];firstphase=results['candidates']['offline']['end_to_end']['by_phase'];basephase=results['baseline']['by_phase']
    nb=nbf.v4.new_notebook();md=nbf.v4.new_markdown_cell;code=nbf.v4.new_code_cell
    nb.cells=[md('# Dance stage mapping: overnight experiments\n\nWe want a useful floor position for each dancer. Formation shapes come later. This notebook records what we trained, what improved, and what still fails. The saved videos are the quickest way to judge the result.'),code("from pathlib import Path\nimport json\nimport pandas as pd\nfrom IPython.display import display, Image, Video\nroot = Path.cwd()\nassert (root / 'reserved_evaluation/results.json').exists(), 'Open this notebook from Dance_Overnight.'\nread = lambda p: json.loads((root / p).read_text())\nfirst = read('reserved_evaluation/results.json')\nfinal = read('backup_evaluation/results.json')\n"),md('## 1. Fix the point before smoothing it\n\nA box bottom moves when a dancer bends, raises a leg, or overlaps another person. We kept YOLO for person boxes and trained a separate small network to predict the center of the actual floor supports and whether that contact is visible. The floor point is transformed onto the mat; then we filter the trajectory.\n\nPipeline: **person boxes → identity tracking → support point + visibility → perspective transform → offline trajectory fit**. The chosen support model uses a pretrained ResNet18 backbone. This is a trained support estimator, not a new YOLO segmentation model.'),md('## 2. Label a support point, not a silhouette\n\nEach crop needs a person box, one floor-support point when visible, and a contact status. Feet, knees, mixed knee/foot support, seated contact, and hands-only support use the center of the primary supports. Hidden, airborne, and uncertain contacts have no invented coordinate. Uncertain examples are excluded from clean supervised training.\n\nA segmentation mask alone would not tell us which limb is supporting the dancer. The current evidence supports boxes plus these point/status labels as the next annotation task.'),code("display(Image(filename=str(root / 'figures/label_examples.jpg'), width=1100))"),md(f'## 3. Use varied frames, not every neighboring frame\n\nThe expanded support set contains **56 training frames**, giving **{training["training_boxes"]} usable dancer crops**. Nine separate development frames provide 154 clean validation crops. Earlier experiments used smaller sets. We ran 23 support-model training configurations and two detector fine-tunes, then compared tracking and filtering choices.\n\nAdjacent crops are correlated; this is still one choreography. The detector fine-tune used 26 unique training frames, with extra sampling of floor poses. The support-label collection is not automatically complete detector ground truth.'),code("display(Image(filename=str(root / 'figures/training_comparison.png'), width=950))\ndisplay(Image(filename=str(root / 'figures/selected_training_curves.png'), width=850))"),md('## 4. Keep evaluation separate\n\nThe first selection used development labels only. We then tested nine reserved frames from source 4800–5080. After seeing those results, we changed the trajectory filter and froze it again. Seven different reserved frames from 5125–5265 tested that second choice. Neither reserved set entered training.\n\nAll reference labels are assistant visual estimates, not an independent human audit. They need teammate review. Dense crowds contain unresolved bodies, so these scores concern the annotated, distinguishable dancers. Missing predictions count as misses. Errors use percent of mat width, not meters.'),code("def row(name, a):\n    return {'Method': name, 'Within 1%': f\"{a['correct_by_tolerance_pct_width']['1']}/{a['visible_references']}\", 'Within 3%': f\"{a['correct_by_tolerance_pct_width']['3']}/{a['visible_references']}\", 'Available': a['available_visible'], 'Median error (%)': round(a['median_error_pct'], 2), 'p90 error (%)': round(a['p90_error_pct'], 2)}\ndisplay(pd.DataFrame([row('Previous pipeline', first['baseline']['all']), row('First frozen offline pipeline', first['candidates']['offline']['end_to_end']['all'])]))"),md(f'The first test improved from **{baseline["correct_by_tolerance_pct_width"]["3"]} to {first["correct_by_tolerance_pct_width"]["3"]} correct positions out of 135** at the 3% tolerance. In its moving/crowded phase, the count improved from **{basephase["transition_and_crowd"]["correct_by_tolerance_pct_width"]["3"]} to {firstphase["transition_and_crowd"]["correct_by_tolerance_pct_width"]["3"]} out of 55**. The new pipeline incorrectly emitted a measured point for 4/24 hidden references, versus 2/24 before. Visibility is not solved.\n\nWith the same detector, IDs, visibility, and filter, replacing box bottoms with learned support improved 3%-correct positions from 80 to 110/135. This isolates the value of the support point.'),md('## 5. Fit a smooth trajectory without pretending hidden points are visible\n\nThe second filter fits the whole trajectory, reduces the effect of outliers, and penalizes abrupt changes in velocity. Short gaps can be estimated; longer gaps stay unknown. It uses future frames and is suitable for recorded-video analysis.\n\nOn the already inspected first test, paired acceleration p99 fell from 1.45 to 0.05 percentage points of mat width per frame². The 3%-correct count changed from 110 to 107/135. That replay is diagnostic, not a fresh test. Synthetic movement checks show that offline smoothing can spread a real movement slightly before and after it happens; this is not zero-latency tracking.'),code("display(pd.DataFrame([row('Box bottoms; identical new pipeline', final['candidates']['same_pipeline_box_bottom']['end_to_end']['all']), row('Learned support; identical new pipeline', final['candidates']['round2']['end_to_end']['all'])]))\ndisplay(Video('videos/final_reserved.mp4', embed=False, width=1100))"),md('## 6. Watch the longer stress test\n\nThe 97-second replay starts from twenty reviewed boxes at source frame 4420 and tracks forward and backward. It contains training frames, so it is a qualitative stress test. Solid dots are model outputs, hollow dots are estimates, and unknown locations are omitted.\n\nThe longer clip still loses bodies and identities in dense, seated groups. Do not interpret twenty remembered IDs as twenty observed dancers. The short held-pose identity audit found 73 correct IDs among 73 matched boxes out of 80 references; that does not establish identity accuracy during the later crowd.'),code("display(Video('videos/full_section.mp4', embed=False, width=1100))"),md(f'## 7. What to do next\n\nKeep the separate support-point model and the offline trajectory fit. Ask teammates to **review the prepared 56 training images**, split 19/19/18, rather than label thousands of adjacent frames. Keep the nine development images separate and assign an independent reviewer. The guide includes a CVAT import and export check.\n\nFor detector training, additionally verify every distinguishable dancer has a box; the crop-label set is not exhaustive. For identity training, image-local IDs are insufficient: use short reviewed tracks across overlap events. Finish that tracking work before measuring formation accuracy.\n\nThe current mat transform is unchanged and its physical dimensions are unverified. At the back of this view, a few pixels of point error can produce a substantial map error.\n\nWarm detector-plus-support inference measured about **{runtime["combined_core_inference_fps"]:.1f} frames/s** on the RTX4070 Laptop GPU, excluding tracking, decoding and rendering. Ten crop/flip views improve robustness but add cost. This is an offline prototype.'),md('## 8. Reproduce and review\n\nThe notebook reads saved results and does not start training. `REPRODUCE.txt` describes the supplied source clips, weights, manifests and commands. `CVAT_Review/GUIDE.html` explains the labels. Original frozen results remain separate from later diagnostic experiments.\n\nSources: [Ultralytics tracking](https://docs.ultralytics.com/modes/track/), [pose labels](https://docs.ultralytics.com/datasets/pose/), [ByteTrack](https://arxiv.org/abs/2110.06864), [BoT-SORT](https://arxiv.org/abs/2206.14651), [OSNet](https://arxiv.org/abs/1905.00953).')]
    index=next(i for i,c in enumerate(nb.cells) if c.cell_type=='markdown' and c.source.startswith('## 6.'))
    nb.cells.insert(index,md(f'On this final crowd sample, learned support gave **{second["correct_by_tolerance_pct_width"]["1"]}/77 versus {box["correct_by_tolerance_pct_width"]["1"]}/77** within the stricter1% tolerance. At3%, the difference was only **{second["correct_by_tolerance_pct_width"]["3"]} versus {box["correct_by_tolerance_pct_width"]["3"]}**. Its p90 error was worse ({second["p90_error_pct"]:.2f}% versus {box["p90_error_pct"]:.2f}%). The gain is useful but not uniform, and missing/incorrect associations remain the main practical limit. The one airborne reference was incorrectly emitted as a measured point.'))
    late_md,late_html=supplement()
